  "type": "module",
  "main": "./src/index.ts",
  "scripts": {
    "check": "node scripts/run-bun.mjs --check src/index.ts src/distillation.ts test/index.test.ts test/fixtures.test.ts test/current-e2e-replay.ts test/historical-replay.ts",
