    "replay:historical": "OPENCODE_DB_PATH=${OPENCODE_DB_PATH:-$HOME/.local/share/opencode/opencode.db} node scripts/run-bun.mjs test/historical-replay.ts"
  },
  "description": "OpenCode plugin that reduces repeated OMO task output, safely distills reconstructable background results, and compresses built-in tool descriptions.",
  "publishConfig": {
    "access": "public"
  },
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src/*.ts",
    "scripts/*.mjs",
    "config.json",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
