    "opencode",
    "opencode-plugin",
    "oh-my-openagent",
    "omo",
    "token-optimization",
    "context-compression"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cat4869/token-lean.git"
  },
  "homepage": "https://github.com/cat4869/token-lean#readme",
  "bugs": {
    "url": "https://github.com/cat4869/token-lean/issues"
  },
