import type { Plugin } from "@opencode-ai/plugin"
import { appendFileSync, readFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join, dirname } from "node:path"
import { fileURLToPath } from "node:url"
import {
  compressKnownTaskEnvelope,
  DEFAULT_BACKGROUND_DISTILL_MIN_CHARS,
  DEFAULT_BACKGROUND_DISTILL_MIN_SAVINGS,
  distillBackgroundResult,
} from "./distillation.ts"

/**
 * token-lean — OpenCode plugin for token optimization.
 *
 * Features (all controlled by config.json feature flags):
 * - Plan 5: system.transform pass-through (infrastructure)
 * - Plan 6: messages.transform (reminder dedup + result compression)
 * - Plan 4: tool.definition (tool description intelligent compression)
 */

// --- Config loading ---
interface TokenLeanConfig {
  reminderDedup?: boolean
  resultCompression?: boolean
  backgroundResultDistillation?: boolean
  backgroundDistillMinChars?: number
  backgroundDistillMinSavings?: number
  runtimeProbe?: boolean
  toolDescriptionCompress?: boolean
  dedupErrorMapMax?: number
}

const DEFAULT_DEDUP_ERROR_MAP_MAX = 1000
const RUNTIME_PROBE_PATH = join(tmpdir(), "token-lean-runtime-probe.jsonl")
const RESULT_COMPRESSED_MARKER = "[result compressed by token-lean"

function hasResidualResultBoilerplate(output: string): boolean {
  return output.includes("<task_metadata>") ||
    output.includes("to continue: task(") ||
    output.includes("## SUBAGENT WORK COMPLETED") ||
    output.includes("**Subagent Response:**")
}

function writeRuntimeProbe(enabled: boolean | undefined, entry: Record<string, unknown>): void {
  if (!enabled) return
  try {
    appendFileSync(RUNTIME_PROBE_PATH, JSON.stringify({ time: Date.now(), ...entry }) + "\n")
  } catch {
    // Diagnostics must never affect the OpenCode session.
  }
}

function loadConfig(): TokenLeanConfig {
  try {
    // Try to read config.json from plugin directory
    // In Bun runtime, import.meta.url is available
    const pluginDir = dirname(fileURLToPath(import.meta.url))
    const configPath = join(pluginDir, "..", "config.json")
    const raw = readFileSync(configPath, "utf-8")
    return JSON.parse(raw)
  } catch {
    // Default: all features enabled
    return {
      reminderDedup: true,
      resultCompression: true,
      backgroundResultDistillation: false,
      toolDescriptionCompress: true,
      dedupErrorMapMax: DEFAULT_DEDUP_ERROR_MAP_MAX,
    }
  }
}

// --- Layer 3: Continuous failure degradation ---
// Per-session error counter: >=3 errors in same session -> disable reminderDedup for that session
const dedupErrorCounts = new Map<string, number>()
const DEDUP_ERROR_THRESHOLD = 3

// FIFO eviction: cap the Map to prevent unbounded growth in long-running tasks.
// A disabled session's entry is a dead record (the transform hook early-returns for it),
// so it naturally drifts to the front of the Map and is evicted first.
function recordDedupError(sessionId: string, max: number): number {
  const count = (dedupErrorCounts.get(sessionId) || 0) + 1
  dedupErrorCounts.set(sessionId, count)
  if (dedupErrorCounts.size > max) {
    const oldest = dedupErrorCounts.keys().next().value
    if (oldest !== undefined) dedupErrorCounts.delete(oldest)
  }
  return count
}

// --- Reminder summary template ---
function buildVerificationSummary(sessionId: string | undefined): string {
  const sid = sessionId || "ses_UNKNOWN"
  return `[验证协议摘要（完整版见本 session 上文）]
子 agent 可能在撒谎。必须对抗性验证：
1. **先读码**: git diff --stat → Read 每个变更文件 → Grep TODO/FIXME/HACK/as any/@ts-ignore
2. **自动化检查**: lsp_diagnostics 每文件(零错误) → 测试(模块后全套) → build(退出0)
3. **实际运行**(用户可见变更): playwright/curl/interactive_bash — 真正交互验证
4. **Gate**: 能解释每行代码? 亲眼见到运行? 确认无破坏? 全部 YES 才放行
任何失败 → task(task_id="${sid}", prompt="fix: 具体问题")`
}

// --- Regex patterns (audit-confirmed anchors) ---
// Matches the FULL verification protocol block (NOT the bare label in leadReminder)
const VERIFICATION_PROTOCOL_RE = /\*\*THE SUBAGENT JUST CLAIMED THIS TASK IS DONE/i
// Matches the orchestrator reminder block
const ORCHESTRATOR_RE = /\*\*BOULDER STATE:\*\*/
// Matches <system-reminder> wrapper
const SYSTEM_REMINDER_RE = /<system-reminder>([\s\S]*?)<\/system-reminder>/gi

// Extract sessionId from a tool part's metadata
function extractSessionId(parts: any[]): string | undefined {
  for (const part of parts) {
    if (part?.type === "tool" && part?.state?.status === "completed") {
      const sid = part?.state?.metadata?.sessionId
      if (typeof sid === "string" && sid.length > 0) return sid
    }
  }
  return undefined
}

// --- Plan 4: Tool description intelligent compression ---
// Capability keywords that should survive built-in tool description compression.
const CAPABILITY_KEYWORDS = [
  // Multimedia
  'image', 'images', 'PDF', 'PDFs', 'video', 'audio', 'binary',
  // Path/range
  'absolute path', 'offset', 'limit', 'line number', 'recursive',
  // Search/pattern
  'regex', 'glob', 'pattern', 'multiline',
  // Edit capabilities
  'replaceAll', 'oldString', 'newString', 'exact match', 'overwrite',
  // Shell capabilities
  'persistent', 'shell session', 'timeout', 'background', 'workdir',
  // Safety limits
  'safety limits', 'file limit',
  // Network
  'redirect', 'URL',
]

function compressToolDescription(original: string): string {
  // fail-safe 0: too short to compress
  if (original.length < 200) return original

  try {
    // Step 1: Extract first sentence (to first period/newline/exclamation)
    const firstSentenceMatch = original.match(/^(.+?[.。!！\n])/)
    const firstSentence = firstSentenceMatch
      ? firstSentenceMatch[1].trim()
      : original.split('\n')[0].trim()

    // Step 2: Scan for capability keywords in full text
    const foundKeywords = CAPABILITY_KEYWORDS.filter((kw) =>
      original.toLowerCase().includes(kw.toLowerCase())
    )

    // Step 3: Assemble compressed result
    let compressed = firstSentence
    if (foundKeywords.length > 0) {
      // Check if first sentence already includes the keywords
      const firstHasKeywords = foundKeywords.some((kw) =>
        firstSentence.toLowerCase().includes(kw.toLowerCase())
      )
      if (!firstHasKeywords) {
        compressed += ` Supports: ${foundKeywords.join(', ')}.`
      }
    }

    // fail-safe 1: compressed is longer than original → keep original
    if (compressed.length >= original.length) return original

    // fail-safe 2: compressed too short (< 30 chars) → keep original
    if (compressed.length < 30) return original

    return compressed
  } catch {
    // Any extraction error → return original (fail-safe)
    return original
  }
}

// Built-in tools whitelist (audit confirmed: only compress these)
const BUILTIN_TOOLS = new Set([
  'read', 'edit', 'bash', 'grep', 'glob', 'write', 'list', 'fetch'
])

// --- Result compression strip functions ---
// Applied to task/background_output tool outputs in messages.transform.
const STRIPS: { name: string; fn: (s: string) => string }[] = [
  // <task_metadata> XML block (task() only; no-op for background_output)
  {
    name: "task_metadata",
    fn: (s: string) => s.replace(/<task_metadata>[\s\S]*?<\/task_metadata>/g, ""),
  },
  // taskResumeInfo continuation hint line
  {
    name: "taskResumeInfo",
    fn: (s: string) => s.replace(/\nto continue: task\(task_id=[^\n]*\n?/g, ""),
  },
  // Decorative header (Plan 7 方案 A)
  {
    name: "subagentHeader",
    fn: (s: string) => s.replace(/^## SUBAGENT WORK COMPLETED\s*$/gm, ""),
  },
  // Subagent Response label (Plan 7 方案 A)
  {
    name: "subagentLabel",
    fn: (s: string) => s.replace(/^\*\*Subagent Response:\*\*\s*$/gm, ""),
  },
]

function hasPartUpdateClient(client: any): boolean {
  return typeof client?.part?.update === "function"
}

function hasRawPatchClient(client: any): boolean {
  return typeof client?._client?.patch === "function"
}

async function patchPart(client: any, directory: string, part: any): Promise<boolean> {
  try {
    let response: any
    if (hasPartUpdateClient(client)) {
      response = await client.part.update({
        sessionID: part.sessionID,
        messageID: part.messageID,
        partID: part.id,
        directory,
        part,
      })
    } else if (hasRawPatchClient(client)) {
      // OpenCode 1.17.15's legacy plugin facade has no `part.update`, but its
      // injected SDK transport still carries the in-process fetch implementation.
      response = await client._client.patch({
        url: "/session/{sessionID}/message/{messageID}/part/{partID}",
        path: {
          sessionID: part.sessionID,
          messageID: part.messageID,
          partID: part.id,
        },
        query: { directory },
        headers: { "Content-Type": "application/json" },
        body: part,
      })
    } else {
      return false
    }
    if (!response) return false
    if (response.error) return false
    return Boolean(response.data ?? response)
  } catch {
    return false
  }
}

const tokenLeanPlugin: Plugin = async ({ client, directory }) => {
  const config = loadConfig()
  const updatingParts = new Set<string>()
  writeRuntimeProbe(config.runtimeProbe, {
    kind: "plugin-init",
    clientPartUpdate: hasPartUpdateClient(client),
    clientTransportPatch: hasRawPatchClient(client),
    resultCompression: config.resultCompression === true,
    backgroundResultDistillation: config.backgroundResultDistillation === true,
  })

  return {
    event: async ({ event }: any) => {
      if (!config.resultCompression) return
      if (event?.type !== "message.part.updated" && event?.type !== "message.part.updated.1") return
      const part = event?.properties?.part ?? event?.part
      writeRuntimeProbe(config.runtimeProbe, {
        kind: "part-event",
        eventType: event?.type,
        partSource: event?.properties?.part ? "properties" : event?.part ? "direct" : "missing",
        partType: part?.type,
        tool: part?.tool,
        status: part?.state?.status,
        hasPartID: Boolean(part?.id),
        hasSessionID: Boolean(part?.sessionID),
        hasMessageID: Boolean(part?.messageID),
      })
      if (part?.type !== "tool" || part?.state?.status !== "completed") return
      if (part.tool !== "task" && part.tool !== "background_output") return
      if (typeof part?.state?.output !== "string" || part.state.output.length === 0) return
      if (part.state.output.includes(RESULT_COMPRESSED_MARKER) && !hasResidualResultBoilerplate(part.state.output)) return
      if (!part.id || !part.sessionID || !part.messageID) return
      if (!hasPartUpdateClient(client) && !hasRawPatchClient(client)) return

      const key = `${part.sessionID}:${part.messageID}:${part.id}`
      if (updatingParts.has(key)) return
      updatingParts.add(key)
      try {
        const childSessionId = part?.state?.metadata?.sessionId
        if (typeof childSessionId !== "string" || childSessionId.length === 0) return

        let nextOutput = part.state.output
        let distillation: DistillationResult | undefined
        if (part.tool === "background_output" && config.backgroundResultDistillation) {
          try {
            const messages = await (client as any)?.session?.messages?.({
              path: { id: childSessionId },
            })
            distillation = distillBackgroundResult(
              nextOutput,
              messages,
              config.backgroundDistillMinChars ?? DEFAULT_BACKGROUND_DISTILL_MIN_CHARS,
              config.backgroundDistillMinSavings ?? DEFAULT_BACKGROUND_DISTILL_MIN_SAVINGS,
            )
            nextOutput = distillation.output
            writeRuntimeProbe(config.runtimeProbe, {
              kind: "distillation-result",
              tool: part.tool,
              reason: distillation.reason,
              changed: distillation.changed,
              originalChars: distillation.originalChars,
              distilledChars: distillation.distilledChars,
            })
          } catch (error) {
            console.error("[token-lean] background distillation query failed", {
              sessionID: part.sessionID,
              messageID: part.messageID,
              partID: part.id,
              error: error instanceof Error ? error.message : String(error),
            })
          }
        }

        nextOutput = compressKnownTaskEnvelope(nextOutput, childSessionId)
        if (
          nextOutput !== part.state.output &&
          !nextOutput.includes(RESULT_COMPRESSED_MARKER)
        ) {
          nextOutput = nextOutput.trimEnd() +
            `\n[result compressed by token-lean, full session: ${childSessionId}]`
        }
        if (nextOutput === part.state.output) return

        const updatedPart = {
          ...part,
          state: { ...part.state, output: nextOutput },
        }
        const patched = await patchPart(client, directory, updatedPart)
        writeRuntimeProbe(config.runtimeProbe, {
          kind: "patch-result",
          tool: part.tool,
          patched,
          originalChars: part.state.output.length,
          updatedChars: nextOutput.length,
        })
        if (!patched) {
          console.error("[token-lean] part PATCH failed", {
            sessionID: part.sessionID,
            messageID: part.messageID,
            partID: part.id,
          })
        } else if (distillation?.changed) {
          console.info("[token-lean] background result distilled", {
            sessionID: part.sessionID,
            messageID: part.messageID,
            partID: part.id,
            originalChars: distillation.originalChars,
            distilledChars: nextOutput.length,
            assistantTextParts: distillation.assistantTextParts,
          })
        }
      } finally {
        updatingParts.delete(key)
      }
    },

    // === Plan 5: Pass-through system.transform ===
    "experimental.chat.system.transform": async (input, output) => {
      try {
        // Pass-through: do not modify output.system
        // This hook exists as infrastructure for future features
        return
      } catch (error) {
        // Layer 1 exception handling: fail-open, log error
        console.error("[token-lean] system.transform error:", error)
        // Return without modifying — system prompt stays as-is
        return
      }
    },

    // === Plan 6: Reminder dedup with actionable summary ===
    "experimental.chat.messages.transform": async (input: any, output: any) => {
      // Feature flag check
      if (!config.reminderDedup && !config.resultCompression) return

      try {
        // Layer 2: Top-level exception handling
        const messages = output?.messages
        if (!Array.isArray(messages)) return

        // Per-request local Set (no persistent state, no memory leak)
        const seenTypes = new Set<string>()

        // Layer 3: Check if this session has exceeded error threshold
        const requestSessionId = input?.sessionID || ""
        const dedupDisabled = Boolean(
          requestSessionId && dedupErrorCounts.get(requestSessionId) >= DEDUP_ERROR_THRESHOLD,
        )

        // Iterate oldest → newest
        for (let i = 0; i < messages.length; i++) {
          try {
            // Layer 1: Per-message exception handling
            const msg = messages[i]
            if (!msg || !Array.isArray(msg.parts)) continue

            // Extract sessionId from this message's tool parts (for summary template)
            const sessionId = extractSessionId(msg.parts)

            for (let j = 0; j < msg.parts.length; j++) {
              try {
                const part = msg.parts[j]
                if (!part) continue

                // Layer 4: OMO content protection - skip synthetic parts
                // Simplified from plan SHA-256 snapshot: synthetic flag covers main risk
                if (part.synthetic === true) continue

                // Only process tool parts with completed state
                if (part.type !== "tool") continue
                if (!part.state || part.state.status !== "completed") continue

                const outputText = part.state.output
                if (typeof outputText !== "string") continue

                // Check if this output contains reminder blocks
                if (config.reminderDedup && !dedupDisabled) {
                  let modified = false
                  let newOutput = outputText

                  // Process each <system-reminder> block
                  newOutput = newOutput.replace(SYSTEM_REMINDER_RE, (match, content) => {
                    // Detect reminder type using audit-confirmed anchors
                    let reminderType: string | null = null

                    if (VERIFICATION_PROTOCOL_RE.test(content)) {
                      reminderType = "VERIFICATION_PROTOCOL"
                    } else if (ORCHESTRATOR_RE.test(content)) {
                      reminderType = "ORCHESTRATOR"
                    }

                    if (!reminderType) return match // Not a known reminder, keep as-is

                    if (!seenTypes.has(reminderType)) {
                      // First occurrence: keep full text
                      seenTypes.add(reminderType)
                      return match
                    }

                    // Subsequent occurrence: replace with actionable summary
                    modified = true
                    const summary = buildVerificationSummary(sessionId)
                    return `<system-reminder>\n${summary}\n</system-reminder>`
                  })

                  if (modified) {
                    part.state.output = newOutput
                  }
                }

                // === Result compression ===
                if (config.resultCompression) {
                  const toolName = (part as any).tool
                  if (toolName === "task" || toolName === "background_output") {
                    const current = part.state.output
                    if (typeof current === "string" && current.length > 0) {
                      let compressed = current
                      for (const strip of STRIPS) {
                        try {
                          compressed = strip.fn(compressed)
                        } catch (e) {
                          console.error(`[token-lean] strip error (${strip.name}):`, e)
                        }
                      }
                      if (compressed !== current) {
                        const sid = part.state?.metadata?.sessionId
                        if (
                          typeof sid === "string" &&
                          sid.length > 0 &&
                          !compressed.includes(RESULT_COMPRESSED_MARKER)
                        ) {
                          compressed =
                            compressed.trimEnd() +
                            `\n[result compressed by token-lean, full session: ${sid}]`
                        }
                        part.state.output = compressed
                      }
                    }
                  }
                }
              } catch (partError) {
                // Layer 1: Skip this part, continue
                console.error(`[token-lean] messages.transform part error (msg ${i}, part ${j}):`, partError)
              }
            }
          } catch (msgError) {
            // Layer 1: Skip this message, continue
            console.error(`[token-lean] messages.transform message error (msg ${i}):`, msgError)
            // Layer 3: Track errors per session (bounded Map via FIFO eviction)
            if (requestSessionId) {
              const count = recordDedupError(requestSessionId, config.dedupErrorMapMax ?? DEFAULT_DEDUP_ERROR_MAP_MAX)
              if (count === DEDUP_ERROR_THRESHOLD) {
                console.error(`[token-lean] Layer 3: disabling dedup for session ${requestSessionId} (${count} errors)`)
              }
            }
          }
        }
      } catch (topError) {
        // Layer 2: Complete pass-through
        console.error("[token-lean] messages.transform top-level error:", topError)
        return
      }
    },

    // === Plan 4: Tool description intelligent compression ===
    "tool.definition": async (input: any, output: any) => {
      // Feature flag check
      if (!config.toolDescriptionCompress) return

      try {
        // Layer 2: Top-level exception handling
        // Only compress built-in tools (not MCP/plugin tools)
        const toolID = input?.toolID
        if (!toolID || !BUILTIN_TOOLS.has(toolID)) return

        const originalDescription = output?.description
        if (typeof originalDescription !== "string") return

        try {
          // Layer 1: Per-tool compression
          const compressed = compressToolDescription(originalDescription)

          // Only write if actually changed
          if (compressed !== originalDescription) {
            output.description = compressed
            // Layer 4: NEVER assign output.parameters
          }
        } catch (compressError) {
          // Layer 1: Skip this tool, keep original description
          console.error(`[token-lean] tool.definition compress error (${toolID}):`, compressError)
        }
      } catch (topError) {
        // Layer 2: Complete pass-through
        console.error("[token-lean] tool.definition top-level error:", topError)
        return
      }
    },
  }
}

export default tokenLeanPlugin
